:root {
  /* Colors */
  --color-paper-canvas: #ffffff;
  --color-mist-canvas: #f8f6f8;
  --color-sage-surface: #edf2f0;
  --color-carbon-ink: #1d161d;
  --color-graphite-caption: #574e57;
  --color-pewter-line: #786c78;
  --color-ash-caption: #a89ea8;
  --color-cream-ink: #faf9fa;
  --color-concrete-rule: #eeecee;
  --color-jet-fill: #2a232a;
  --color-plum-signal: #6a2f8d;
  --color-lilac-wash: #f1e6f8;
  --color-orchid-pulse: #b054e7;

  /* Typography — Font Families */
  --font-roobert: "Roobert", "Space Grotesk", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-neue-haas-grotesk-text: "Neue Haas Grotesk Text", "Arimo", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-dm-mono: "DM Mono", "IBM Plex Mono", ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;

  /* Typography — Scale */
  --text-small: 12px;
  --leading-small: 1;
  --tracking-small: -0.24px;
  --text-caption: 13px;
  --leading-caption: 1;
  --tracking-caption: 1px;
  --text-body-sm: 14px;
  --leading-body-sm: 1.14;
  --tracking-body-sm: 0.28px;
  --text-body: 16px;
  --leading-body: 1.25;
  --tracking-body: -0.16px;
  --text-body-lg: 18px;
  --leading-body-lg: 1.33;
  --tracking-body-lg: -0.18px;
  --text-subheading: 20px;
  --leading-subheading: 1.25;
  --tracking-subheading: -0.4px;
  --text-heading-sm: 28px;
  --leading-heading-sm: 1.25;
  --tracking-heading-sm: -0.56px;
  --text-heading: 40px;
  --leading-heading: 1.15;
  --tracking-heading: -0.8px;
  --text-heading-lg: 48px;
  --leading-heading-lg: 1;
  --tracking-heading-lg: -0.96px;
  --text-display: 64px;
  --leading-display: 1;
  --tracking-display: -2.56px;

  /* Typography — Weights */
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-bold: 700;

  /* Spacing */
  --spacing-2: 2px;
  --spacing-4: 4px;
  --spacing-6: 6px;
  --spacing-8: 8px;
  --spacing-10: 10px;
  --spacing-12: 12px;
  --spacing-13: 13px;
  --spacing-14: 14px;
  --spacing-16: 16px;
  --spacing-24: 24px;
  --spacing-32: 32px;
  --spacing-36: 36px;
  --spacing-48: 48px;
  --spacing-64: 64px;
  --spacing-128: 128px;
  --spacing-160: 160px;

  /* Layout */
  --layout-page-max-width: 1440px;
  --layout-content-max-width: 1280px;
  --layout-hero-text-width: 700px;
  --layout-section-gap: 160px;
  --layout-section-gap-mobile: 64px;
  --layout-card-padding: 32px;
  --layout-element-gap: 10px;
  --layout-nav-height: 64px;

  /* Border Radius */
  --radius-sm: 2px;
  --radius-sm-2: 3px;
  --radius-md: 4px;
  --radius-md-2: 5px;
  --radius-lg: 16px;
  --radius-full: 100px;

  /* Named Radii */
  --radius-small-elements: 2px;
  --radius-tags: 2px;
  --radius-badges: 3px;
  --radius-buttons: 4px;
  --radius-inner-tiles: 5px;
  --radius-cards: 16px;
  --radius-pills: 100px;
  --radius-avatars: 100%;
  --radius-images: 0px;
  --radius-inputs: 0px;
  --radius-nav: 0px;

  /* Shadows */
  --shadow-subtle: rgba(0, 0, 0, 0.1) 0px 1px 2px -1px, rgba(0, 0, 0, 0.1) 0px 1px 3px 0px;
  --shadow-sm: rgba(0, 0, 0, 0.05) 0px 4px 4px 0px;
  --shadow-sm-2: rgba(0, 0, 0, 0.5) 0px 0px 12px 0px inset;
  --shadow-md: rgba(0, 0, 0, 0.05) 0px 2px 4px 0px, rgba(76, 76, 76, 0.2) 0px 0px 10px 0px;
  --shadow-lg: rgba(0, 0, 0, 0.1) -9.5px 0px 19px 0px;

  /* Surfaces */
  --surface-mist-canvas: #f8f6f8;
  --surface-paper-canvas: #ffffff;
  --surface-sage-surface: #edf2f0;
  --surface-plum-signal: #6a2f8d;
  --surface-jet-fill: #2a232a;
}

